{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])

    # Build node dict and children map
    node_dict = {}
    children_map = {}
    for n in nodes:
        nid = n['id']
        node_dict[nid] = n
        children_map.setdefault(n['parent'], []).append(nid)

    # Initialize retained set and symbol count
    retained = set(node_dict.keys())
    symbol_count = {}
    for n in nodes:
        sym = n['symbol']
        symbol_count[sym] = symbol_count.get(sym, 0) + 1

    # Sort nodes: deeper first, then by id ascending
    sorted_nodes = sorted(nodes, key=lambda x: (-x['depth'], x['id']))

    removed_order = []

    for n in sorted_nodes:
        nid = n['id']
        if not n['removable']:
            continue
        if n['symbol'] in required_symbols:
            continue
        # Check if any child is still retained
        has_retained_child = any(cid in retained for cid in children_map.get(nid, []))
        if has_retained_child:
            continue
        # Remove node
        removed_order.append(nid)
        retained.remove(nid)
        sym = n['symbol']
        symbol_count[sym] -= 1
        # No need to check required symbols because node is not required

    # Build result
    retained_ids = sorted(retained)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_ids
    }"
}
